onChange.script:
if currentValue.value is not None:
	maxTime = system.date.toMillis(currentValue.value)/1000*1000
	minTime = maxTime - float(self.custom.slider.minutesBack) * 60000

	if self.custom.slider.timeSlider >= self.custom.slider.range.max:
		self.custom.slider.time = maxTime
		self.custom.slider.timeSlider = maxTime
	elif self.custom.slider.timeSlider == self.custom.slider.range.min:
		if self.custom.slider.time > self.custom.slider.timeSlider:
			self.custom.slider.time = self.custom.slider.timeSlider
	elif self.custom.slider.timeSlider > self.custom.slider.range.min:
		if self.custom.slider.time != self.custom.slider.timeSlider:
			self.custom.slider.time = self.custom.slider.timeSlider

	self.custom.slider.range = {'max':maxTime, 'min': minTime}

